import * as T from './vendor/three.module.js';
import {torchModel} from './torches.js';
function texture(kind){if(typeof document==='undefined'||!document.createElement)return null;const c=document.createElement('canvas');if(!c.getContext)return null;c.width=c.height=128;const x=c.getContext('2d');x.fillStyle=kind==='grimoire'?'#482a67':kind==='quiver'?'#74462c':'#6c5747';x.fillRect(0,0,128,128);for(let i=0;i<128;i+=4){x.strokeStyle=i%8?'#ffffff0b':'#00000022';x.beginPath();x.moveTo(i,0);x.lineTo(i+Math.sin(i)*3,128);x.stroke()}x.strokeStyle='#b69b66';x.lineWidth=4;x.strokeRect(9,9,110,110);if(kind==='grimoire'){x.strokeStyle='#c4a3e9';x.lineWidth=3;x.beginPath();x.arc(64,64,32,0,Math.PI*2);x.stroke();x.beginPath();x.moveTo(64,30);for(const a of [144,288,72,216,0]){const r=a*Math.PI/180-Math.PI/2;x.lineTo(64+Math.cos(r)*34,64+Math.sin(r)*34)}x.stroke();x.fillStyle='#e5bd6c';x.fillRect(58,59,12,12)}const map=new T.CanvasTexture(c);map.colorSpace=T.SRGBColorSpace;return map}
export function equipmentModel(parent,id){const g=new T.Group();g.name=id+'-model';parent.add(g);const mat=(color,kind)=>new T.MeshStandardMaterial({color,map:kind?texture(kind):null,roughness:.8});const brass=mat(0xbca36c),metal=mat(0x9daeb9);function add(geo,m,x=0,y=0,z=0){const o=new T.Mesh(geo,m);o.position.set(x,y,z);g.add(o);return o}function box(w,h,d,m,x=0,y=0,z=0){return add(new T.BoxGeometry(w,h,d),m,x,y,z)}
 if(id==='grimoire'){const cover=mat(0xffffff,'grimoire');box(.31,.4,.075,mat(0xe4d8b4));box(.35,.44,.022,cover,0,0,.05);box(.35,.44,.022,cover,0,0,-.05);box(.035,.44,.12,cover,-.17);for(const side of [-1,1])for(const y of [-.18,.18])box(.045,.045,.015,brass,side*.14,y,.069);for(let i=0;i<4;i++)box(.29,.003,.002,mat(0xa79b81),0,-.12+i*.08,.039);box(.025,.12,.008,mat(0xa3413d),.06,-.24,.01)}
 else if(id==='shield_fine'){const wood=mat(0xffffff,'shield_fine');add(new T.CylinderGeometry(.28,.28,.07,12),wood).rotation.x=Math.PI/2;add(new T.TorusGeometry(.28,.025,6,16),metal,0,0,.05);add(new T.ConeGeometry(.08,.13,8),metal,0,0,.10).rotation.x=Math.PI/2;box(.035,.44,.02,brass,0,0,.055)}
 else if(id==='quiver'){const leather=mat(0xffffff,'quiver');add(new T.CylinderGeometry(.12,.095,.42,10),leather);for(let i=0;i<4;i++){const x=(i-1.5)*.045,z=(i%2)*.04;add(new T.CylinderGeometry(.008,.008,.58,5),mat(0xc9ac73),x,.2,z);add(new T.ConeGeometry(.024,.07,4),metal,x,.52,z);box(.04,.08,.008,mat(0xb6b9a6),x,.4,z)}}return g}
export function offhandModel(parent,id,fireMap){const root=new T.Group();root.name='offhand-'+id;root.userData.itemId=id;parent.add(root);const item=id==='torch'?torchModel(root,{map:fireMap,handheld:true}):equipmentModel(root,'grimoire');if(id==='torch'){item.scale.setScalar(.72);item.position.set(.07,.02,0);item.rotation.z=-.18;const flame=item.children.find(o=>o.isSprite);if(flame)flame.position.y=.65}const skin=new T.MeshStandardMaterial({color:0xb68c69,emissive:0x20150e,emissiveIntensity:.2}),sleeve=new T.MeshStandardMaterial({color:0x51475c});for(const [r,l,y,z,m] of [[.04,.08,id==='torch'?.12:-.21,.04,skin],[.05,.27,-.34,.15,sleeve]]){const o=new T.Mesh(new T.CapsuleGeometry(r,l,4,8),m);o.position.set(.07,y,z);if(id==='torch'){o.position.set(r===.04?.07:-.06,r===.04?.18:.09,r===.04?.035:.18);o.rotation.x=r===.04?-1.03:-.35;o.rotation.z=r===.04?.12:-.95}else o.rotation.x=-.4;root.add(o)}root.userData.animate=time=>{root.position.set(id==='torch'?-.43:-.38,id==='torch'?-.63:-.42,-.77);root.rotation.set(id==='torch'?-.08:.12,.24,.13);item.userData.animate?.(time)};root.userData.animate(0);return root}
export function disposeEquipment(root,sharedMap){if(!root)return;root.removeFromParent();const geos=new Set(),mats=new Set(),maps=new Set();root.traverse(o=>{if(o.geometry)geos.add(o.geometry);for(const m of Array.isArray(o.material)?o.material:o.material?[o.material]:[]){mats.add(m);if(m.map&&m.map!==sharedMap)maps.add(m.map)}});for(const x of [...geos,...mats,...maps])x.dispose()}
